CREATE TABLE "better_supabase"."conversation_members" (
  "conversation_id" uuid                     NOT NULL,
  "tenant_id"       uuid                     NOT NULL,
  "user_id"         uuid                     NOT NULL,
  "role"            text                     NOT NULL DEFAULT 'member'::text,
  "notify"          text                     NOT NULL DEFAULT 'all'::text,
  "last_read_at"    timestamp with time zone,
  "joined_at"       timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "conversation_members_notify_check" CHECK ((notify = ANY (ARRAY['all'::text, 'mentions'::text, 'none'::text]))),
  CONSTRAINT "conversation_members_pkey" PRIMARY KEY (conversation_id, user_id),
  CONSTRAINT "conversation_members_role_check" CHECK ((role = ANY (ARRAY['owner'::text, 'member'::text])))
);

ALTER TABLE "better_supabase"."conversation_members"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."conversations" (
  "id"              uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"       uuid                     NOT NULL,
  "kind"            text                     NOT NULL,
  "access"          text                     NOT NULL DEFAULT 'members'::text,
  "subject_type"    text,
  "subject_id"      text,
  "title"           text,
  "member_key"      text,
  "created_by"      uuid,
  "last_message_at" timestamp with time zone,
  "archived_at"     timestamp with time zone,
  "created_at"      timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"      timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "conversations_access_check" CHECK ((access = ANY (ARRAY['members'::text, 'tenant'::text, 'subject'::text]))),
  CONSTRAINT "conversations_check1" CHECK (((access <> 'subject'::text) OR (subject_type IS NOT NULL))),
  CONSTRAINT "conversations_check" CHECK (((subject_type IS NULL) = (subject_id IS NULL))),
  CONSTRAINT "conversations_kind_check" CHECK ((kind = ANY (ARRAY['channel'::text, 'dm'::text, 'group_dm'::text, 'subject'::text, 'inbox'::text]))),
  CONSTRAINT "conversations_pkey" PRIMARY KEY (id),
  CONSTRAINT "conversations_title_check" CHECK (((title IS NULL) OR ((length(title) >= 1) AND (length(title) <= 200))))
);

ALTER TABLE "better_supabase"."conversations"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."message_edits" (
  "id"         uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"  uuid                     NOT NULL,
  "message_id" uuid                     NOT NULL,
  "body"       text                     NOT NULL,
  "document"   jsonb,
  "edited_by"  uuid,
  "edited_at"  timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "message_edits_pkey" PRIMARY KEY (id)
);

ALTER TABLE "better_supabase"."message_edits"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."messages" (
  "id"              uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"       uuid                     NOT NULL,
  "conversation_id" uuid                     NOT NULL,
  "parent_id"       uuid,
  "thread_id"       uuid,
  "author_id"       uuid,
  "body"            text                     NOT NULL DEFAULT ''::text,
  "document"        jsonb,
  "mentions"        uuid[]                   NOT NULL DEFAULT '{}'::uuid[],
  "mention_scope"   text,
  "broadcast"       boolean                  NOT NULL DEFAULT false,
  "reply_count"     integer                  NOT NULL DEFAULT 0,
  "last_reply_at"   timestamp with time zone,
  "reply_user_ids"  uuid[]                   NOT NULL DEFAULT '{}'::uuid[],
  "pinned_at"       timestamp with time zone,
  "pinned_by"       uuid,
  "resolved_at"     timestamp with time zone,
  "resolved_by"     uuid,
  "scheduled_for"   timestamp with time zone,
  "sent_at"         timestamp with time zone,
  "edited_at"       timestamp with time zone,
  "deleted_at"      timestamp with time zone,
  "created_at"      timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "messages_body_check" CHECK ((length(body) <= 40000)),
  CONSTRAINT "messages_check" CHECK (((thread_id IS NULL) = (parent_id IS NULL))),
  CONSTRAINT "messages_mention_scope_check" CHECK ((mention_scope = ANY (ARRAY['channel'::text, 'here'::text]))),
  CONSTRAINT "messages_pkey" PRIMARY KEY (id)
);

ALTER TABLE "better_supabase"."messages"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."thread_reads" (
  "tenant_id"       uuid                     NOT NULL,
  "user_id"         uuid                     NOT NULL,
  "conversation_id" uuid                     NOT NULL,
  "thread_id"       uuid,
  "last_read_at"    timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "thread_reads_user_id_conversation_id_thread_id_key" UNIQUE NULLS NOT DISTINCT (user_id, conversation_id, thread_id)
);

ALTER TABLE "better_supabase"."thread_reads"
  ENABLE ROW LEVEL SECURITY;

