CREATE INDEX messaging_conversations_list_idx ON better_supabase.conversations USING btree (tenant_id, last_message_at DESC NULLS LAST, id);

CREATE UNIQUE INDEX messaging_conversations_member_key_idx ON better_supabase.conversations USING btree (tenant_id, kind, member_key)
  WHERE (member_key IS NOT NULL);

CREATE UNIQUE INDEX messaging_conversations_subject_idx ON better_supabase.conversations USING btree (tenant_id, subject_type, subject_id)
  WHERE (kind = 'subject'::text);

CREATE INDEX messaging_edits_message_idx ON better_supabase.message_edits USING btree (message_id, edited_at);

CREATE INDEX messaging_members_user_idx ON better_supabase.conversation_members USING btree (user_id, tenant_id);

CREATE INDEX messaging_messages_author_idx ON better_supabase.messages USING btree (author_id);

CREATE INDEX messaging_messages_conversation_idx ON better_supabase.messages USING btree (conversation_id, sent_at, id)
  WHERE ((thread_id IS NULL) OR broadcast);

CREATE INDEX messaging_messages_due_idx ON better_supabase.messages USING btree (scheduled_for)
  WHERE (sent_at IS NULL);

CREATE INDEX messaging_messages_parent_idx ON better_supabase.messages USING btree (parent_id)
  WHERE (parent_id IS NOT NULL);

CREATE INDEX messaging_messages_pinned_idx ON better_supabase.messages USING btree (conversation_id, pinned_at DESC)
  WHERE (pinned_at IS NOT NULL);

CREATE INDEX messaging_messages_thread_idx ON better_supabase.messages USING btree (thread_id, sent_at, id)
  WHERE (thread_id IS NOT NULL);

CREATE INDEX messaging_reads_conversation_idx ON better_supabase.thread_reads USING btree (conversation_id);

CREATE INDEX messaging_reads_thread_idx ON better_supabase.thread_reads USING btree (thread_id);

CREATE TRIGGER bs_messaging_message_broadcast
  AFTER INSERT OR UPDATE ON better_supabase.messages
  FOR EACH ROW
  EXECUTE FUNCTION better_supabase.messaging_message_broadcast();

CREATE TRIGGER bs_messaging_message_written
  AFTER INSERT OR UPDATE OF sent_at, deleted_at ON better_supabase.messages
  FOR EACH ROW
  EXECUTE FUNCTION better_supabase.messaging_message_written();

CREATE TRIGGER bs_search_message_index
  AFTER INSERT OR DELETE OR UPDATE OF id, tenant_id, body, deleted_at ON better_supabase.messages
  FOR EACH ROW
  EXECUTE FUNCTION better_supabase.search_index_row('message', 'id');

CREATE POLICY "activity_entries_read" ON "better_supabase"."activity_entries"
  FOR SELECT
  TO "authenticated"
  USING
    (((organization_id IN ( SELECT better_supabase.tenant_ids_with('activity.read'::text) AS tenant_ids_with)) AND ((subject_type IS NULL) OR (subject_id IS NULL) OR (NOT
    (subject_type = ANY
    ('{comment,message,conversation,company,person,deal,engagement,work_item,employee,product,product_variant,calendar_event,document,customer,drive_node,application,project,task}'::text[]))) OR better_supabase.activity_subject_readable(subject_type, subject_id))));

CREATE POLICY "attachments_insert" ON "better_supabase"."attachments"
  FOR INSERT
  TO "authenticated"
  WITH CHECK (((uploaded_by = ( SELECT auth.uid() AS uid)) AND COALESCE(better_supabase.can('tenant'::text, organization_id,
CASE subject_type
    WHEN 'comment'::text THEN 'comments.create'::text
    WHEN 'message'::text THEN 'messages.send'::text
    WHEN 'conversation'::text THEN 'messages.send'::text
    ELSE 'attachments.upload'::text
END), false) AND better_supabase.attachment_subject_readable(subject_type, subject_id, organization_id) AND ( SELECT better_supabase.actor_may_write() AS actor_may_write)));

CREATE POLICY "conversation_members_read" ON "better_supabase"."conversation_members"
  FOR SELECT
  TO "authenticated"
  USING (((user_id = ( SELECT auth.uid() AS uid)) OR (EXISTS ( SELECT 1
   FROM better_supabase.conversations c
  WHERE (c.id = conversation_members.conversation_id)))));

CREATE POLICY "conversations_read" ON "better_supabase"."conversations"
  FOR SELECT
  TO "authenticated"
  USING (((tenant_id IN ( SELECT better_supabase.tenant_ids_with('messages.read'::text) AS tenant_ids_with)) AND
CASE access
    WHEN 'tenant'::text THEN true
    WHEN 'members'::text THEN better_supabase.is_conversation_member(id)
    WHEN 'subject'::text THEN COALESCE(better_supabase.can_subject(subject_type, subject_id, 'read'::text), false)
    ELSE false
END));

CREATE POLICY "message_edits_read" ON "better_supabase"."message_edits"
  FOR SELECT
  TO "authenticated"
  USING ((EXISTS ( SELECT 1
   FROM better_supabase.messages m
  WHERE (m.id = message_edits.message_id))));

CREATE POLICY "messages_read" ON "better_supabase"."messages"
  FOR SELECT
  TO "authenticated"
  USING ((((sent_at IS NOT NULL) OR (author_id = ( SELECT auth.uid() AS uid))) AND (EXISTS ( SELECT 1
   FROM better_supabase.conversations c
  WHERE (c.id = messages.conversation_id)))));

CREATE POLICY "thread_reads_read" ON "better_supabase"."thread_reads"
  FOR SELECT
  TO "authenticated"
  USING ((user_id = ( SELECT auth.uid() AS uid)));

CREATE POLICY "bs_messaging_broadcast" ON "realtime"."messages"
  FOR INSERT
  TO "authenticated"
  WITH
    CHECK
    (((extension = ANY (ARRAY['broadcast'::text, 'presence'::text])) AND (( SELECT realtime.topic() AS topic) ~~ ('messages:'::text || '%'::text)) AND
    better_supabase.conversation_topic_allowed(substr(( SELECT realtime.topic() AS topic), 10)) AND ( SELECT better_supabase.actor_may_write() AS actor_may_write)));

CREATE POLICY "bs_messaging_receive" ON "realtime"."messages"
  FOR SELECT
  TO "authenticated"
  USING
    (((EXTENSION = ANY (ARRAY['broadcast'::text, 'presence'::text])) AND (( SELECT realtime.topic() AS topic) ~~ ('messages:'::text || '%'::text)) AND
    better_supabase.conversation_topic_allowed(substr(( SELECT realtime.topic() AS topic), 10))));

